const lessons=[{id:'architecture',file:'01_arquitectura.md',folder:'01_arquitectura',title:'Arquitectura de un LLM'},{id:'tools',file:'02_funciones.md',folder:'02_funciones',title:'Funciones y herramientas'},{id:'jwt',file:'03_jwt.md',folder:'03_seguridad',title:'JWT y límites de acceso'},{id:'idempotency',file:'04_idempotencia.md',folder:'04_confiabilidad',title:'Idempotencia'}];
let active='architecture',completed=new Set(),events=[];const $=s=>document.querySelector(s);
function log(message,tone=''){events.unshift({message,tone,at:new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})});$('#events').innerHTML=events.map(e=>`<div class="event ${e.tone}"><time>${e.at}</time>${e.message}</div>`).join('');}
function nav(){$('#lesson-list').innerHTML=lessons.map((l,i)=>`<button class="lesson ${l.id===active?'active':''}" data-lesson="${l.id}"><span class="file">${i?'·':'◇'}</span>${l.file}${completed.has(l.id)?'<span class="check">✓</span>':''}</button>`).join('');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>select(b.dataset.lesson));$('#progress-count').textContent=completed.size;$('#progress-bar').style.width=`${completed.size*25}%`;}
const box=(lang,content)=>`<div class="codeblock"><div class="codehead">${lang}</div><pre>${content}</pre></div>`;
function doc(id){const done='<div class="next-step"><span>¿Ya te resulta claro? Marcá el módulo y seguí.</span><button class="next-button" id="done">Entendido ✓</button></div>';
if(id==='architecture')return `<div class="eyebrow">01 · mapa mental</div><h1>Arquitectura de un sistema con LLM</h1><p class="lead">Un LLM no es tu aplicación completa. Es un componente probabilístico dentro de un sistema que prepara contexto, decide qué puede hacer y valida lo que devuelve.</p><div class="callout"><strong>Idea clave.</strong> Separá lo que <em>razona</em> (el modelo) de lo que tiene efectos reales: datos, pagos, correos o cambios de estado.</div><h2>Las capas que importan</h2><div class="definition-grid"><div class="definition"><span>01 · interfaz</span><b>Cliente</b><p>Recoge intención y muestra estados comprensibles.</p></div><div class="definition"><span>02 · orquestación</span><b>Backend / agente</b><p>Arma contexto, aplica reglas y coordina.</p></div><div class="definition"><span>03 · inteligencia</span><b>Modelo LLM</b><p>Clasifica, redacta o propone una acción.</p></div><div class="definition"><span>04 · verdad</span><b>Servicios y datos</b><p>APIs y base de datos; aquí viven los efectos.</p></div></div><h2>¿Por qué existe el backend?</h2><p>Porque ahí controlás credenciales, límites, auditoría, reintentos y autorización. Una respuesta probabilística sólo se convierte —o no— en acción tras aplicar reglas de negocio.</p>${box('pseudocódigo de orquestación','const contexto = buscarConocimiento(pregunta)\nconst respuesta = await modelo.generar({ pregunta, contexto })\n\nif (respuesta.quiereHerramienta) {\n  return ejecutarHerramientaValidada(respuesta.llamada)\n}\nreturn respuesta.texto')}<p>En el panel, avanzá el mensaje y observá cómo cruza las responsabilidades.</p>${done}`;
if(id==='tools')return `<div class="eyebrow">02 · acciones controladas</div><h1>Funciones y herramientas</h1><p class="lead">El modelo puede <strong>proponer</strong> una llamada a función, pero no debería tener capacidad ilimitada para ejecutar lo que imagina.</p><div class="callout"><strong>Regla de oro.</strong> El modelo elige una intención estructurada; el servidor valida el esquema, verifica permisos y ejecuta la acción real.</div><h2>El contrato de una herramienta</h2><p>Una herramienta tiene nombre, objetivo y parámetros. Es una API pequeña que el modelo sabe invocar.</p>${box('JSON Schema simplificado','{\n  "name": "buscar_pedidos",\n  "description": "Busca pedidos del usuario autenticado",\n  "parameters": { "estado": "pendiente | enviado" }\n}')}<h2>Secuencia segura</h2><ul><li>Tu backend envía sólo herramientas permitidas para este usuario.</li><li>El modelo responde con argumentos estructurados.</li><li>El backend valida tipos, permisos y reglas de negocio.</li><li>Ejecuta la función y devuelve su resultado, si hace falta.</li></ul><p>Probá el panel: la herramienta aparece primero como propuesta y sólo después se ejecuta.</p>${done}`;
if(id==='jwt')return `<div class="eyebrow">03 · identidad y permisos</div><h1>JWT: una credencial verificable, no una caja fuerte</h1><p class="lead">Un JSON Web Token transporta <em>claims</em>: datos mínimos sobre quién es alguien y qué puede hacer.</p><div class="callout"><strong>No cifrado por defecto.</strong> El contenido de un JWT común se puede decodificar. La firma prueba que no fue alterado; no oculta sus datos. Nunca pongas secretos dentro.</div><h2>Las tres partes</h2><div class="definition-grid"><div class="definition"><span>header</span><b>Cómo se firmó</b><p>Algoritmo y tipo de token.</p></div><div class="definition"><span>payload</span><b>Claims</b><p><code>sub</code>, <code>role</code>, <code>exp</code>.</p></div><div class="definition"><span>signature</span><b>Integridad</b><p>Evita que alteren header o payload.</p></div><div class="definition"><span>exp</span><b>Caducidad</b><p>Limita una credencial filtrada.</p></div></div><h2>Verificación por request</h2>${box('middleware conceptual',"const token = leerBearer(request)\nconst claims = verificarFirmaYExpiracion(token)\n\nif (!claims || !puede(claims, 'orders:read')) {\n  return Response.json({ error: 'forbidden' }, { status: 403 })\n}")}<p>El token identifica; la autorización decide. Para acciones sensibles, consultá además la fuente de verdad.</p>${done}`;
return `<div class="eyebrow">04 · confiabilidad</div><h1>Idempotencia: reintentar sin cobrar dos veces</h1><p class="lead">Una operación es idempotente cuando repetir la misma petición produce el mismo efecto observable que haberla hecho una única vez.</p><div class="callout"><strong>El problema real.</strong> La red puede fallar después de que el servidor actuó, pero antes de que el cliente recibiera la respuesta. ¿Reintentás o duplicás el cobro?</div><h2>La clave de idempotencia</h2><p>El cliente genera una clave única por intención y la envía en cada reintento. El servidor guarda el resultado asociado a esa clave.</p>${box('flujo del servidor','if (existeResultado(request.idempotencyKey)) {\n  return resultadoGuardado(request.idempotencyKey)\n}\n\nconst pago = await cobrar(request.body)\nguardarResultado(request.idempotencyKey, pago)\nreturn pago')}<h2>Qué guardar</h2><ul><li>Clave, usuario y huella de parámetros.</li><li>Estado: en progreso, completado o fallido recuperable.</li><li>La respuesta final o referencia durable al recurso.</li></ul><p>En el simulador enviá dos veces la misma intención: la segunda devuelve el resultado guardado.</p>${done}`}
function lab(id){if(id==='architecture')return `<p class="lab-copy">Trazá un mensaje a través de responsabilidades separadas.</p><div class="flow" id="arch-flow">${['INPUT|“Quiero ver mis pedidos”|La UI captura intención y estado.','ORQUESTADOR|Construye contexto|Autentica, limita y prepara la consulta.','LLM|Decide: buscar_pedidos|Propone una herramienta estructurada.','SERVICIO|Fuente de verdad|Ejecuta sólo con permiso válido.'].map((x,i)=>{let[a,b,c]=x.split('|');return `<div class="flow-node ${i?'':'active'}"><div class="node-top"><span>0${i+1} / ${a}</span><span>${i===2?'✦':'↗'}</span></div><b>${b}</b><small>${c}</small></div>${i<3?'<div class="arrow">↓</div>':''}`}).join('')}</div><button class="lab-action" id="run">Avanzar mensaje →</button>`;
if(id==='tools')return `<p class="lab-copy">El LLM recibe una pregunta y propone una llamada tipada.</p><div class="prompt-box"><b>USUARIO</b><br>¿Qué pedidos pendientes tengo?</div><div class="tool-card"><span>TOOLS[0]</span><b>buscar_pedidos({ estado })</b></div><div id="result" class="json-box">Esperando decisión del modelo…</div><button class="lab-action" id="run">Pedir llamada de herramienta</button>`;
if(id==='jwt')return `<p class="lab-copy">Inspeccioná los claims y simulá una petición protegida.</p><div class="jwt-token"><span class="jwt-segment one">eyJhbGciOiJIUzI1NiJ9</span>.<span class="jwt-segment two">eyJzdWIiOiI0MiIsInJvbGUiOiJ1c2VyIn0</span>.<span class="jwt-segment three">firma_verificada</span></div><div class="token-table"><div class="token-row"><span>sub</span><b>user_42</b></div><div class="token-row"><span>scope</span><b>orders:read</b></div><div class="token-row"><span>exp</span><b id="exp">válido · 14 min</b></div><div class="token-row"><span>firma</span><b id="sign">sin verificar</b></div></div><div id="result" class="request-card"><span>GET /api/orders</span><strong>Listo para verificar token</strong></div><button class="lab-action" id="run">Verificar y autorizar</button>`;
return `<p class="lab-copy">Una misma intención llega dos veces por un corte de red.</p><div class="prompt-box"><b>POST /payments</b><br>Idempotency-Key: pay_7da2b<br>amount: 2500</div><div id="result" class="request-card"><span>ESTADO</span><strong>Aún no se procesó el pago</strong></div><button class="lab-action" id="run">Enviar pago</button>`}
function bind(){ $('#done').onclick=()=>{completed.add(active);nav();log(`Lección marcada como comprendida: ${lessons.find(l=>l.id===active).file}`,'good')};let phase=0;$('#run').onclick=()=>{phase++;let r=$('#result');if(active==='architecture'){let nodes=[...document.querySelectorAll('.flow-node')];nodes.forEach(n=>n.classList.remove('active'));nodes[phase%nodes.length].classList.add('active');let msg=['Entrada recibida en interfaz','Contexto mínimo preparado','Modelo solicitó buscar_pedidos','Servicio respondió con datos autorizados'][phase%4];log(msg,phase%4===3?'good':'');$('#status-text').textContent=msg}if(active==='tools'){if(phase===1){r.textContent='{\n  "tool_call": "buscar_pedidos",\n  "arguments": { "estado": "pendiente" }\n}\n\n✓ esquema validado; ejecutar?';log('El modelo propuso una llamada; el backend valida argumentos','warn')}else{r.textContent='Resultado: 2 pedidos pendientes.\nEl modelo puede explicarlo al usuario.';log('Resultado de herramienta incorporado a la respuesta','good')}}if(active==='jwt'){let sign=$('#sign');if(phase%2){sign.textContent='válida ✓';r.className='request-card success';r.innerHTML='<span>200 OK</span><strong>Autorizado: orders:read</strong>';log('Firma y expiración verificadas; scope permitido','good')}else{$('#exp').textContent='expirado';sign.textContent='expirada';r.className='request-card warn';r.innerHTML='<span>401 UNAUTHORIZED</span><strong>Renová sesión, no reutilices token</strong>';log('Token rechazado por expiración','warn')}}if(active==='idempotency'){if(phase===1){r.className='request-card success';r.innerHTML='<span>201 CREATED</span><strong>Pago pay_884 creado · $2.500</strong>';$('#run').textContent='Reintentar misma petición';log('Clave pay_7da2b registrada junto al resultado','good')}else{r.className='request-card success';r.innerHTML='<span>200 REPLAYED</span><strong>Mismo pago pay_884 · no se cobró otra vez</strong>';$('#run').textContent='Resultado reutilizado ✓';log('Reintento detectado: resultado almacenado','good')}}}}
function select(id){active=id;let l=lessons.find(x=>x.id===id);$('#tab-label').textContent=l.file;$('#crumb-folder').textContent=l.folder;$('#scenario-label').textContent=`escenario 0${lessons.indexOf(l)+1}`;$('#document').innerHTML=doc(id);$('#visual-lab').innerHTML=lab(id);nav();bind();log(`Módulo abierto: ${l.title}`)}
$('#clear-events').onclick=()=>{events=[];$('#events').innerHTML='<div class="event">Sin eventos todavía.</div>'};$('#reset-button').onclick=()=>{completed.clear();events=[];select('architecture');log('Laboratorio reiniciado')};select(active);log('Bienvenido. Elegí un módulo o interactuá con el panel.','good');
